import random, math

random.seed(42)

depts = {"Legal": 4, "Research": 8, "Finance": 8, "Engineering": 9, "Sales": 11}
emp_dept = []
for d, cnt in depts.items():
    emp_dept.extend([d]*cnt)
dept_names = list(depts.keys())

def sim_episode(d1_mode="disjoint18", d2_mode="none"):
    mole = random.randrange(40)
    decoy = random.choice([i for i in range(40) if i != mole])
    V = 1.0
    docs = []
    def get_emps(ds):
        return {i for i, d in enumerate(emp_dept) if d in ds}
    docs.append((1, get_emps(["Legal", "Research"]), False, None))
    docs.append((1, get_emps(["Legal", "Engineering"]), False, None))
    docs.append((1, get_emps(["Legal", "Research"]), False, None))
    docs.append((1, get_emps(["Finance", "Sales"]), False, None))

    # Order employees so each dept is spread evenly across buckets!
    # Priority: Eng(9), Fin(8), Sales(11) [1 doc], then Research(8) [2 docs], then Legal(4) [3 docs]
    ordered = []
    for d in ["Sales", "Engineering", "Finance", "Research", "Legal"]:
        ordered.extend([i for i, ed in enumerate(emp_dept) if ed == d])

    if d1_mode == "disjoint18":
        # Interleave across 6 buckets (c1:0,1,2, c2:0,1,2) for first 36 employees!
        c1 = {ordered[idx]: (idx // 2) % 3 for idx in range(0, 36, 2)}
        c2 = {ordered[idx]: (idx // 2) % 3 for idx in range(1, 36, 2)}
        docs.append((1, set(c1.keys()), True, c1))
        docs.append((1, set(c2.keys()), True, c2))
        V -= 0.02
    elif d1_mode == "disjoint20":
        c1 = {ordered[idx]: (idx // 2) % 3 for idx in range(0, 40, 2)}
        c2 = {ordered[idx]: (idx // 2) % 3 for idx in range(1, 40, 2)}
        docs.append((1, set(c1.keys()), True, c1))
        docs.append((1, set(c2.keys()), True, c2))
        V -= 0.02
    elif d1_mode == "ortho27":
        # First 27 employees get BOTH c1 and c2 with orthogonal 3x3!
        c1 = {ordered[idx]: idx % 3 for idx in range(27)}
        c2 = {ordered[idx]: (idx // 3) % 3 for idx in range(27)}
        docs.append((1, set(c1.keys()), True, c1))
        docs.append((1, set(c2.keys()), True, c2))
        V -= 0.02
    elif d1_mode == "ortho18":
        c1 = {ordered[idx]: idx % 3 for idx in range(18)}
        c2 = {ordered[idx]: (idx // 3) % 3 for idx in range(18)}
        docs.append((1, set(c1.keys()), True, c1))
        docs.append((1, set(c2.keys()), True, c2))
        V -= 0.02

    leaked_doc_ids = set()
    pending_leaks = []
    logp = [0.0]*40

    for day in range(1, 22):
        if day == 2:
            logp[decoy] = -1e9
        if day > 1:
            n_new = random.choice([2, 3, 4])
            for _ in range(n_new):
                d2 = random.sample(dept_names, 2)
                docs.append((day, get_emps(d2), False, None))

        for sday, didx, svar in pending_leaks:
            if sday == day:
                _, recips, is_c, vmap = docs[didx]
                for e in range(40):
                    if e not in recips:
                        logp[e] = -1e9
                    elif is_c:
                        if vmap[e] == svar:
                            logp[e] += math.log(0.95)
                        else:
                            n_other = len(set(vmap.values())) - 1
                            logp[e] += math.log(0.05 / max(1, n_other))

        if day > 1:
            for e in range(40):
                p_ah = 0.3 if e == mole else 0.1
                ah = 1 if random.random() < p_ah else 0
                if e != mole and e != decoy and random.random() < (1.0/38.0):
                    ah += 1
                logp[e] += ah * math.log(0.30 / 0.126) if ah > 0 else math.log(0.70 / 0.874)
            alive = sorted([e for e in range(40) if logp[e] > -1e8], key=lambda x: -logp[x])
            for e in alive[:6]:
                evasive = random.random() < (0.24 if e == mole else 0.20)
                logp[e] += math.log(1.2 if evasive else (0.76/0.80))

        mx = max(logp)
        probs = [math.exp(lp - mx) if lp > -1e8 else 0.0 for lp in logp]
        s = sum(probs)
        probs = [p/s for p in probs]
        best_p = max(probs)
        best_e = probs.index(best_p)

        if best_p >= 0.99 or (day == 21 and best_p * V - (1 - best_p) > 0):
            return V if best_e == mole else -1.0, day

        if day == 2 and d2_mode == "disjoint19":
            rem39 = [e for e in ordered if e != decoy]
            c1 = {rem39[idx]: (idx // 2) % 3 for idx in range(0, 39, 2)}
            c2 = {rem39[idx]: (idx // 2) % 3 for idx in range(1, 39, 2)}
            docs.append((2, set(c1.keys()), True, c1))
            docs.append((2, set(c2.keys()), True, c2))
            V -= 0.02

        sig_suspects = [e for e in range(40) if probs[e] >= 0.003]
        if day >= 3 and 2 <= len(sig_suspects) <= 20:
            pool = list(sig_suspects)
            while len(pool) < 4:
                extra = random.choice([e for e in range(40) if e not in pool and e != decoy])
                pool.append(extra)
            vmap1 = {e: idx % 3 for idx, e in enumerate(pool)}
            docs.append((day, set(pool), True, vmap1))
            V -= 0.01
            if len(sig_suspects) >= 3:
                vmap2 = {e: (idx // 3) % 3 if len(pool) > 3 else (idx + 1) % 3 for idx, e in enumerate(pool)}
                if len(set(vmap2.values())) >= 2:
                    docs.append((day, set(pool), True, vmap2))
                    V -= 0.01

        elig = [idx for idx, (d, recips, _, _) in enumerate(docs)
                if day - 2 <= d <= day and mole in recips and idx not in leaked_doc_ids]
        if elig and random.random() < 0.65:
            weights = [(1.0 - len(docs[idx][1])/40.0) if docs[idx][2] else 1.0 for idx in elig]
            chosen = random.choices(elig, weights=weights, k=1)[0]
            leaked_doc_ids.add(chosen)
            V = max(0.0, V - 0.05)
            delay = random.choice([2, 3])
            _, _, is_c, vmap = docs[chosen]
            svar = None
            if is_c:
                true_v = vmap[mole]
                svar = true_v if (random.random() < 0.95 or len(set(vmap.values())) == 1) else random.choice([v for v in set(vmap.values()) if v != true_v])
            pending_leaks.append((day + delay, chosen, svar))

    return 0.0, 21

for d1 in ["disjoint18", "disjoint20", "ortho27", "ortho18"]:
    for d2 in ["none", "disjoint19"]:
        res = [sim_episode(d1, d2) for _ in range(3000)]
        avg_s = sum(r[0] for r in res)/len(res)
        avg_d = sum(r[1] for r in res)/len(res)
        w = sum(1 for r in res if r[0] < 0)
        print(f"d1={d1:10s} d2={d2:10s}: avg_score={avg_s:.4f}, avg_day={avg_d:.2f}, wrongs={w}")

import math

cands = {
    "e16": {"c2_2": "A"},
    "e30": {"c2_2": "A"},
    "e34": {"c2_2": "C"},
    "e04": {"c2_2": "B"},
}

# Exact access log counts across Days 1-6 for e16, e30, e34, e04:
# Day 1-5: nh = {"e16": 5, "e30": 8, "e34": 2, "e04": 7}, ah = {"e16": 1, "e30": 0, "e34": 0, "e04": 0}
# Day 6:   e04: 1F; e16: 1T; e30: 3F; e34: 1F
nh = {"e16": 5, "e30": 11, "e34": 3, "e04": 8}
ah = {"e16": 2, "e30": 0,  "e34": 0, "e04": 0}

# Exact interviews across Days 1-6:
# Day 1-5: ev_t = {"e16": 1, "e30": 0}, ev_f = {"e16": 5, "e30": 4}
# Day 6:   e16: 2F; e30: 1T, 1F
ev_t = {"e16": 1, "e30": 1, "e34": 0, "e04": 0}
ev_f = {"e16": 7, "e30": 5, "e34": 0, "e04": 0}

n_days = 6
for use_nh in [True, False]:
    for dsl_frame in [0.0, 1.0/39.0]:
        logp = {}
        for m in cands:
            lp = math.log(0.95 if cands[m]["c2_2"] == "A" else 0.025)
            inno_ah = 0.1 + 1.0/38.0 + dsl_frame
            if use_nh:
                lp += nh[m] * math.log(0.7 / 0.9) - n_days * (0.7 - 0.9)
            lp += ah[m] * math.log(0.3 / inno_ah) - n_days * (0.3 - inno_ah)
            lp += ev_t[m] * math.log(1.2) + ev_f[m] * math.log(0.76 / 0.80)
            logp[m] = lp
        mx = max(logp.values())
        ps = {m: math.exp(v - mx) for m, v in logp.items()}
        s = sum(ps.values())
        ps = {m: v/s for m, v in ps.items()}
        print(f"use_nh={str(use_nh):5s} dsl_frame={dsl_frame:.3f} -> " +
              ", ".join(f"{m}:{ps[m]:.4f}" for m in ["e16", "e30", "e34", "e04"]))

import math

cands = {"e16": "A", "e30": "A", "e34": "C", "e04": "B"}
nh = {"e16": 5, "e30": 11, "e34": 3, "e04": 8}
ah = {"e16": 2, "e30": 0,  "e34": 0, "e04": 0}
# Day 7 interviews: e16 got 2T, 2F -> total 3T, 9F; e30 got 0T, 2F -> total 1T, 7F
ev_t = {"e16": 3, "e30": 1, "e34": 0, "e04": 0}
ev_f = {"e16": 9, "e30": 7, "e34": 0, "e04": 0}
n_days = 6

for use_nh in [True, False]:
    for dsl_frame in [0.0, 1.0/39.0]:
        logp = {}
        for m, var in cands.items():
            lp = math.log(0.95 if var == "A" else 0.025)
            inno_ah = 0.1 + 1.0/38.0 + dsl_frame
            if use_nh:
                lp += nh[m] * math.log(0.7 / 0.9) - n_days * (0.7 - 0.9)
            lp += ah[m] * math.log(0.3 / inno_ah) - n_days * (0.3 - inno_ah)
            lp += ev_t[m] * math.log(1.2) + ev_f[m] * math.log(0.76 / 0.80)
            logp[m] = lp
        mx = max(logp.values())
        ps = {m: math.exp(v - mx) for m, v in logp.items()}
        s = sum(ps.values())
        ps = {m: v/s for m, v in ps.items()}
        # Compare EV of accusing now (true_V ≈ 0.6175) vs waiting 1 day (true_V ≈ 0.585, catching mole w/ ~0.99)
        p16 = ps["e16"]
        ev_now = p16 * 0.6175 - (1 - p16) * 1.0
        print(f"use_nh={str(use_nh):5s} dsl_frame={dsl_frame:.3f} -> P(e16)={p16:.4f}, P(e30)={ps['e30']:.4f} | EV_accuse_now={ev_now:.4f}")
